import { is_opening_complete, OPENING_REQUEST_MARKER } from '../../../util/openingStatus';
import { CRASH_LANDING_STORY_MARKER } from './crashLandingStory';
import { WRECK_FIXED_OPENING_MARKER } from './wreckOpeningStory';

const ASSISTANT_STORY_RE = /<story>[\s\S]*?<\/story>/i;

/** 是否已开始游玩（已推送开局、旧版迫降正文、变量已就绪，或已有正式剧情楼层） */
export function has_game_started(): boolean {
  if (typeof getChatMessages !== 'function') {
    return false;
  }
  if (is_opening_complete()) {
    return true;
  }
  const msgs = getChatMessages('0-{{lastMessageId}}');
  if (
    msgs.some(
      msg =>
        msg.message.includes(OPENING_REQUEST_MARKER) ||
        msg.message.includes(CRASH_LANDING_STORY_MARKER) ||
        msg.message.includes(WRECK_FIXED_OPENING_MARKER),
    )
  ) {
    return true;
  }
  return msgs.some(
    msg =>
      msg.role === 'assistant' &&
      msg.message_id > 0 &&
      (ASSISTANT_STORY_RE.test(msg.message) || msg.message.includes(WRECK_FIXED_OPENING_MARKER)),
  );
}

/** 侧栏/状态栏是否仍应走标题 → 选路线 → 自定义 开局流程 */
export function should_show_opening_flow(): boolean {
  return !has_game_started();
}
