import { create_default_custom_notes, DEFAULT_CUSTOM_SELECTIONS, } from '../constants/customStartOptions';
import { create_empty_companion } from '../constants/customCompanion';
function create_default_draft() {
    return {
        selections: { ...DEFAULT_CUSTOM_SELECTIONS },
        custom_notes: create_default_custom_notes(),
        no_companion: false,
        companions: [create_empty_companion()],
    };
}
const draft = reactive(create_default_draft());
export function useCustomOpeningDraft() {
    function reset_draft() {
        Object.assign(draft, create_default_draft());
    }
    function load_draft(data) {
        draft.selections = { ...data.selections };
        draft.custom_notes = { ...data.custom_notes };
        draft.no_companion = data.no_companion;
        draft.companions = data.companions.map(c => ({ ...c, skills: { ...c.skills } }));
    }
    function snapshot_draft() {
        return {
            selections: { ...draft.selections },
            custom_notes: { ...draft.custom_notes },
            no_companion: draft.no_companion,
            companions: draft.companions.map(c => ({
                ...c,
                skills: { ...c.skills },
            })),
        };
    }
    return {
        draft,
        reset_draft,
        load_draft,
        snapshot_draft,
    };
}
