import dedent from 'dedent';
import { klona } from 'klona';
import {
  CUSTOM_OPTION_ID,
  CUSTOM_START_SECTIONS,
  type CustomStartNotes,
  type CustomStartSelections,
  get_option_label,
} from '../constants/customStartOptions';
import type { Schema } from '../../../schema';
import { useDataStore } from '../store';

const SEASON_LABELS: Record<string, string> = {
  spring: '春季',
  summer: '夏季',
  autumn: '秋季',
  winter: '冬季',
};

function resolve_section_text(
  section_id: string,
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string {
  const section = CUSTOM_START_SECTIONS.find(s => s.id === section_id);
  if (!section) {
    return '';
  }
  const option_id = selections[section_id];
  if (option_id === CUSTOM_OPTION_ID) {
    return custom_notes[section_id]?.trim() || '（玩家未填写）';
  }
  const label = get_option_label(section_id, option_id);
  const option = section.options.find(o => o.id === option_id);
  if (option?.detail && option.id !== CUSTOM_OPTION_ID) {
    return `${label}（${option.detail}）`;
  }
  return label;
}

function stat_hint_for_section(section_id: string, selections: CustomStartSelections): string {
  switch (section_id) {
    case 'region': {
      const id = selections.region;
      if (id === 'forest_edge') return '世界.当前位置=中央大陆林缘';
      if (id === 'frozen_north') return '世界.当前位置=极北冻土边缘';
      if (id === 'sun_scorch') return '世界.当前位置=烈日荒原';
      if (id === 'west_isles') return '世界.当前位置=西部半岛群';
      return '探索主据点随自定义区域写入';
    }
    case 'identity': {
      const id = selections.identity;
      if (id === 'fallen_god') return '主角.威望≈22，威望称号=坠星神明';
      if (id === 'prisoner') return '主角.威望=0，威望称号=异族战俘';
      return '主角.威望=0，威望称号=无耳族废品雄性';
    }
    case 'camp': {
      const id = selections.camp;
      if (id === 'lone_wolf') return '营地.人口=1，无迫降专属部族事务';
      if (id === 'small_tribe') return '营地.人口=15';
      return '营地.人口=14，向心力/温饱偏低';
    }
    case 'gear': {
      const id = selections.gear;
      if (id === 'backup_power') return '保留部分现代装备与弹药';
      if (id === 'cryo_pod') return '部族事务含「评估休眠舱价值」';
      return '无迫降舱/能量棒等现代物资';
    }
    case 'season':
      return `世界.季节=${SEASON_LABELS[selections.season] ?? '秋季'}`;
    default:
      return '';
  }
}

export function describe_custom_opening_preset(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string[] {
  return CUSTOM_START_SECTIONS.map(section => {
    const text = resolve_section_text(section.id, selections, custom_notes);
    const hint = stat_hint_for_section(section.id, selections);
    return hint ? `${section.title}：${text}｜${hint}` : `${section.title}：${text}`;
  });
}

const REGION_PRESETS: Record<string, { location: string; hub: string; desc: string }> = {
  forest_edge: {
    location: '中央大陆林缘',
    hub: '林缘临时营地',
    desc: '林缘扎营点，可采集浆果与枯枝，偶有狼群出没。',
  },
  frozen_north: {
    location: '极北冻土边缘',
    hub: '冻土边缘营地',
    desc: '寒风凛冽的临时营地，取暖与食物是首要难题。',
  },
  sun_scorch: {
    location: '烈日荒原',
    hub: '荒原临时营地',
    desc: '烈日暴晒、水源稀缺，野兽更具攻击性。',
  },
  west_isles: {
    location: '西部半岛群',
    hub: '半岛临时营地',
    desc: '海风与浅滩并存，可捕鱼拾贝，但高级木材匮乏。',
  },
};

const WRECK_ONLY_PLACE_NAMES = [
  '乱石滩',
  '乱石滩营地',
  '坠星盆地湖畔',
  '湖畔营地',
  '飞船残骸周边',
  '破降舱',
  '针叶林坠',
] as const;

function resolve_region_bundle(region: string, custom_notes: CustomStartNotes) {
  const custom_text = region === CUSTOM_OPTION_ID ? custom_notes.region?.trim() : '';
  const preset = REGION_PRESETS[region];
  const location = preset?.location ?? (custom_text || '自定义区域');
  const hub = preset?.hub ?? `${custom_text || '自定义'}主据点`;
  return { location, hub, desc: preset?.desc ?? (custom_text || '玩家自定义降生区域的主据点。'), preset };
}

export function resolve_custom_hub_name(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string {
  return resolve_region_bundle(selections.region, custom_notes).hub;
}

export function format_custom_preset_instruction(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): string {
  const lines = describe_custom_opening_preset(selections, custom_notes);
  const { location, hub } = resolve_region_bundle(selections.region, custom_notes);
  return dedent`
    【脚本已预置 stat_data，须与下列摘要一致】
    ${lines.map(line => `- ${line}`).join('\n')}

    【正文地名硬约束】
    - 世界.当前位置=${location}；探索区域主据点键名=${hub}（正文写营地时须用此名，禁止另造地名）
    - 禁止出现迫降专属：${WRECK_ONLY_PLACE_NAMES.join('、')}、春/白/林/菊（除非【玩家开局】明确要求）
    - 禁止 replace 为迫降残骸默认（人口14+黑狼羊猫构成、评估残骸价值等），除非【玩家开局】明确要求。
  `;
}

function apply_region(stat: Schema, region: string, custom_notes: CustomStartNotes) {
  const { location, hub: hub_name, desc, preset } = resolve_region_bundle(region, custom_notes);
  stat.世界.当前位置 = location;
  const season = stat.世界.季节;

  stat.探索区域 = {};
  stat.探索区域[hub_name] = {
    描述: desc,
    路程: '即刻',
    危险度: region === 'sun_scorch' ? '中' : '低',
    已掌握: true,
    探索度: region === CUSTOM_OPTION_ID ? 20 : 45,
  };

  if (preset?.location && preset.location !== hub_name) {
    stat.探索区域[preset.location] = {
      描述: `通往${hub_name}的外围地带。`,
      路程: '半个日落',
      危险度: region === 'frozen_north' ? '中' : '低',
      已掌握: false,
      探索度: 15,
    };
  }

  stat.世界.季节 = season;
}

function apply_identity(stat: Schema, identity: string) {
  if (identity === 'fallen_god') {
    stat.主角.威望 = 22;
    stat.主角.威望称号 = '坠星神明';
    return;
  }
  if (identity === 'prisoner') {
    stat.主角.威望 = 0;
    stat.主角.威望称号 = '异族战俘';
    return;
  }
  stat.主角.威望 = 0;
  stat.主角.威望称号 = '无耳族废品雄性';
}

function apply_camp(stat: Schema, camp: string) {
  stat.具名NPC = {};
  stat.未收入兽耳娘 = {};

  if (camp === 'lone_wolf') {
    stat.营地.人口 = 1;
    stat.营地.向心力 = 2;
    stat.营地.向心力_基准 = 2;
    stat.营地.生存指标.温饱度 = 12;
    stat.营地.生存指标.温饱度_基准 = 12;
    stat.营地.生存指标.栖居度 = 5;
    stat.营地.生存指标.栖居度_基准 = 5;
    stat.营地.族人构成 = {};
    stat.营地.当前建筑 = {
      简易窝棚: {
        状态: '漏风',
        描述: '单人勉强栖身的粗糙庇护所',
        功能: '提供基础栖居',
        建筑阶段: '受损',
      },
    };
    stat.部族事务 = {
      熬过第一个寒夜: {
        说明: '孤身一人，必须尽快生火并找到食物。',
        级别: '主要',
      },
    };
    return;
  }

  if (camp === 'small_tribe') {
    stat.营地.人口 = 15;
    stat.营地.向心力 = 8;
    stat.营地.向心力_基准 = 8;
    stat.营地.生存指标.温饱度 = 22;
    stat.营地.生存指标.温饱度_基准 = 22;
    stat.营地.生存指标.栖居度 = 18;
    stat.营地.生存指标.栖居度_基准 = 18;
    stat.营地.族人构成 = { 猫耳娘: 10, 羊角娘: 3, 黑狼娘: 2 };
    stat.部族事务 = {
      熬过第一个寒夜: {
        说明: '小型部落需要稳定食物与防务，避免被外部势力吞并。',
        级别: '主要',
      },
      巩固栅栏: {
        说明: '现有栅栏漏风，需要加固以提升营地防御。',
        级别: '次要',
      },
    };
    return;
  }

  stat.营地.人口 = 14;
  stat.营地.向心力 = 4;
  stat.营地.向心力_基准 = 4;
  stat.营地.生存指标.温饱度 = 14;
  stat.营地.生存指标.温饱度_基准 = 14;
  stat.营地.生存指标.栖居度 = 10;
  stat.营地.生存指标.栖居度_基准 = 10;
  stat.营地.族人构成 = { 猫耳娘: 10, 羊角娘: 2, 黑狼娘: 2 };
  stat.部族事务 = {
    熬过第一个寒夜: {
      说明: '微型营地濒临解散，须尽快稳定食物与人心。',
      级别: '主要',
    },
    稳定人心: {
      说明: '向心力极低，族人对未来充满怀疑。',
      级别: '次要',
    },
  };
}

function apply_gear(stat: Schema, gear: string) {
  if (gear === 'backup_power') {
    stat.主角.随身装备 = {
      战术终端: { 状态: '低功耗运行', 电量或弹药: '中' },
      多功能生存服: { 状态: '恒温受损', 电量或弹药: '无' },
      '9毫米半自动手枪': { 状态: '完好', 电量或弹药: '少量' },
      高周波工兵铲: { 状态: '电池耗尽', 电量或弹药: '无' },
    };
    return;
  }

  if (gear === 'cryo_pod') {
    stat.主角.随身装备 = {
      多功能生存服: { 状态: '恒温受损', 电量或弹药: '无' },
      休眠舱控制器: { 状态: '微电维持', 电量或弹药: '低' },
    };
    stat.部族事务 = {
      ...stat.部族事务,
      评估休眠舱价值: {
        说明: '族人尚不清楚休眠舱意味着什么，需要首领做出判断。',
        级别: '次要',
      },
    };
    return;
  }

  stat.主角.随身装备 = {
    多功能生存服: { 状态: '破损', 电量或弹药: '无' },
  };
}

function apply_season(stat: Schema, season: string) {
  stat.世界.季节 = SEASON_LABELS[season] ?? '秋季';
}

function build_custom_stat(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
  base: Schema,
): Schema {
  const stat = klona(base);
  stat.世界.生存天数 = 1;
  stat.世界.时间 = '18:00';
  stat.世界.飞船能源 = '低功耗';
  stat.营地.篝火燃料.当前 = 0;
  stat.综合事物 = {};
  stat.大地见闻 = {};
  stat.工作队列 = {};
  stat.探索编队 = {};
  stat.幼崽 = {};

  apply_region(stat, selections.region, custom_notes);
  apply_identity(stat, selections.identity);
  apply_camp(stat, selections.camp);
  apply_gear(stat, selections.gear);
  apply_season(stat, selections.season);

  return stat;
}

export async function apply_custom_opening_preset_to_mvu(
  selections: CustomStartSelections,
  custom_notes: CustomStartNotes,
): Promise<void> {
  const store = useDataStore();
  const next = build_custom_stat(selections, custom_notes, store.data);
  Object.assign(store.data, next);
  console.info('[自定义开局] 已按五项设定预置 stat_data');
}
