import { normalize_warehouse_item_name } from '../../../constants/warehouseCatalog';

export type FeedableItem = {
  name: string;
  qty: number;
  desc: string;
  source: 'warehouse' | 'inventory';
  storageKey: string;
};

function canonicalFeedFoodName(name: string): string {
  return normalize_warehouse_item_name(name);
}

function looksLikeFood(name: string, desc = ''): boolean {
  const text = `${name}${desc}`;
  return FOOD_HINTS.some(hint => text.includes(hint));
}

function warehouseFoodDesc(name: string): string {
  if (/方便面/.test(name)) return '箱装方便面，需要热水冲泡';
  if (/罐头/.test(name)) return '箱装肉类罐头，高卡路里速食品';
  if (/肉|块茎|野果|浆果|菌/.test(name)) return '营地储备食材';
  return '部落储物仓中的食物';
}

/** 从部落储物仓（仓库储备）与尚未入库的物品栏合并列出可投喂食物；同名以仓库为准 */
export function listFeedableCampFood(营地: Schema['营地']): FeedableItem[] {
  const merged = new Map<string, FeedableItem>();

  for (const [name, slot] of Object.entries(营地.仓库储备)) {
    if (slot.当前 <= 0) continue;
    const desc = warehouseFoodDesc(name);
    if (!looksLikeFood(name, desc)) continue;
    const canonical = canonicalFeedFoodName(name);
    merged.set(canonical, {
      name: canonical === name ? name : canonical,
      qty: slot.当前,
      desc,
      source: 'warehouse',
      storageKey: name,
    });
  }

  for (const [name, item] of Object.entries(营地.物品栏)) {
    if (item.数量 <= 0) continue;
    if (!looksLikeFood(name, item.描述)) continue;
    const canonical = canonicalFeedFoodName(name);
    if (merged.has(canonical)) continue;
    merged.set(canonical, {
      name,
      qty: item.数量,
      desc: item.描述,
      source: 'inventory',
      storageKey: name,
    });
  }

  return [...merged.values()].sort((a, b) => a.name.localeCompare(b.name, 'zh-CN'));
}

/** @deprecated 仅读物品栏，与储物仓 UI 不一致；请用 listFeedableCampFood */
export function listFeedableWarehouseItems(物品栏: Schema['营地']['物品栏']): FeedableItem[] {
  return listFeedableCampFood({ 物品栏, 仓库储备: {} } as Schema['营地']);
}

export function deductCampFood(营地: Schema['营地'], item: Pick<FeedableItem, 'source' | 'storageKey'>): boolean {
  if (item.source === 'warehouse') {
    const slot = 营地.仓库储备[item.storageKey];
    if (!slot || slot.当前 <= 0) return false;
    slot.当前 -= 1;
    if (slot.当前 <= 0) slot.当前 = 0;
    return true;
  }
  const entry = 营地.物品栏[item.storageKey];
  if (!entry || entry.数量 <= 0) return false;
  entry.数量 -= 1;
  if (entry.数量 <= 0) {
    delete 营地.物品栏[item.storageKey];
  }
  return true;
}
