export const COMPANION_ENTRY_PREFIX = '自定义同伴·';
export const COMPANION_INDEX_ENTRY_NAME = '自定义同伴索引';
function get_char_worldbook_name() {
    const { primary } = getCharWorldbookNames('current');
    if (!primary) {
        throw new Error('未找到角色卡配置，无法保存同伴设定');
    }
    return primary;
}
function build_companion_entry_template(name, content) {
    return {
        name,
        enabled: true,
        strategy: {
            type: 'constant',
            keys: [],
            keys_secondary: { logic: 'and_any', keys: [] },
            scan_depth: 'same_as_global',
        },
        position: {
            type: 'at_depth',
            role: 'system',
            depth: 4,
            order: 110,
        },
        content,
        probability: 100,
        recursion: {
            prevent_incoming: true,
            prevent_outgoing: true,
            delay_until: null,
        },
        effect: {
            sticky: null,
            cooldown: null,
            delay: null,
        },
    };
}
export function format_companion_entry_content(npc) {
    const lines = [
        `<自定义同伴档案·${npc.name.trim()}>`,
        `本条目记录本局自定义同伴设定，供开局生成参照。`,
        '',
        `头像：${format_avatar_for_worldbook(npc.avatar)}`,
        `姓名：${npc.name.trim()}`,
        `性别：${npc.gender.trim() || '（未指定）'}`,
        `外观：${npc.appearance.trim() || '（未填写）'}`,
        `性格：${npc.personality.trim() || '（未填写）'}`,
        `背景与经历：${npc.background.trim() || '（未填写）'}`,
        `技能：狩猎 ${npc.skills.狩猎} | 战斗 ${npc.skills.战斗} | 采集 ${npc.skills.采集} | 后勤 ${npc.skills.后勤}`,
        `好感度：${npc.好感度}`,
        `忠诚度：${npc.忠诚度}`,
        `饱食度：${npc.饱食度}`,
        `体力：${npc.体力}`,
        `与{{user}}关系：${npc.user_relation.trim() || '（未填写）'}`,
        `</自定义同伴档案·${npc.name.trim()}>`,
    ];
    return lines.join('\n');
}
export function format_companion_index_content(companions) {
    if (companions.length === 0) {
        return dedent `
      <自定义同伴索引>
      本局自定义开局未设定同伴（玩家选择「无」）。
      </自定义同伴索引>
    `;
    }
    const names = companions.map(npc => `${COMPANION_ENTRY_PREFIX}${npc.name.trim()}`);
    const body = companions.map(npc => format_companion_entry_content(npc)).join('\n\n');
    return dedent `
    <自定义同伴索引>
    本局自定义同伴共 ${companions.length} 名，须 insert 至【具名NPC】并在 <story> 内首次登场处插入 <npc_panel>：
    ${names.map(n => `- ${n}`).join('\n')}

    ${body}
    </自定义同伴索引>
  `;
}
export function format_companion_floor_block(companions) {
    if (companions.length === 0) {
        return '6. 同伴设定：无（玩家选择不添加自定义同伴）';
    }
    return companions
        .map((npc, index) => {
        const header = `${index + 6}. 同伴「${npc.name.trim()}」档案`;
        return `${header}\n${format_companion_entry_content(npc)}`;
    })
        .join('\n\n');
}
function companion_entry_name(npc) {
    return `${COMPANION_ENTRY_PREFIX}${npc.name.trim()}`;
}
function format_avatar_for_worldbook(avatar) {
    const text = avatar.trim();
    if (!text) {
        return '（未指定，由 AI 依外观描写）';
    }
    if (text.startsWith('data:image')) {
        return '（玩家已在状态栏设定本地头像，依外观字段描写即可）';
    }
    return text;
}
/** 同步自定义同伴世界书条目（每人一条 + 索引条目） */
export async function upsert_companion_worldbook_entries(companions) {
    const worldbook_name = get_char_worldbook_name();
    const target_names = new Set(companions.map(npc => companion_entry_name(npc)));
    target_names.add(COMPANION_INDEX_ENTRY_NAME);
    await deleteWorldbookEntries(worldbook_name, entry => entry.name === COMPANION_INDEX_ENTRY_NAME ||
        (entry.name.startsWith(COMPANION_ENTRY_PREFIX) && !target_names.has(entry.name)));
    const templates = [
        build_companion_entry_template(COMPANION_INDEX_ENTRY_NAME, format_companion_index_content(companions)),
        ...companions.map(npc => build_companion_entry_template(companion_entry_name(npc), format_companion_entry_content(npc))),
    ];
    const worldbook = await getWorldbook(worldbook_name);
    const to_create = templates.filter(template => !worldbook.some(entry => entry.name === template.name));
    const to_update = templates.filter(template => worldbook.some(entry => entry.name === template.name));
    if (to_create.length > 0) {
        await createWorldbookEntries(worldbook_name, to_create);
    }
    if (to_update.length > 0) {
        await updateWorldbookWith(worldbook_name, entries => entries.map(entry => {
            const template = to_update.find(item => item.name === entry.name);
            return template ? { ...entry, ...template } : entry;
        }));
    }
}
/** 清除所有自定义同伴世界书条目 */
export async function clear_companion_worldbook_entries() {
    const worldbook_name = get_char_worldbook_name();
    await deleteWorldbookEntries(worldbook_name, entry => entry.name === COMPANION_INDEX_ENTRY_NAME || entry.name.startsWith(COMPANION_ENTRY_PREFIX));
}
